export function CharacterCounter({
  value = "{{value}}",
  count = {{count}},
  limit = {{limit}},
  nearLimit = {{nearLimit}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430", maxWidth: 320 }}>
      <label htmlFor="charcount-react-field" style={{ display: "block", fontWeight: 600, marginBottom: 6 }}>Bio</label>
      <textarea id="charcount-react-field" aria-describedby="charcount-react-help" readOnly value={value} style={{
        width: "100%", boxSizing: "border-box", minHeight: 76, padding: "10px 12px", borderRadius: 8,
        border: "1.5px solid #24143033", background: "#FAF7F2", color: "#241430", font: "inherit", resize: "vertical" }} />
      <p id="charcount-react-help" role="status" style={{ margin: "6px 2px 0", fontSize: 12,
        color: nearLimit ? "#b3261e" : "#24143099", fontWeight: nearLimit ? 600 : 400 }}>
        {count} / {limit} characters
        {nearLimit && <span style={{ fontWeight: 600 }}> &#8212; approaching the limit</span>}
      </p>
      <style>{`#charcount-react-field:focus-visible { outline: 2px solid ${accent}; outline-offset: 1px; }`}</style>
    </div>
  );
}
